begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_column_privilege('authenticated','public.workout_sessions',c,'UPDATE'),'protected timer field '||c) from unnest(array['manual_paused_at','manual_pause_intervals','timer_revision','started_at','finished_at','effective_finished_at'])c;
select ok(not has_column_privilege('authenticated','public.workout_sessions','manual_paused_at','INSERT'),'cannot start with a fabricated pause');
select ok(not has_function_privilege(r,'public.set_workout_pause(uuid,boolean,integer,uuid)','EXECUTE'),'timer mutation denied to '||r) from unnest(array['anon','service_role'])r;
select ok(not has_function_privilege(r,'public.workout_active_seconds(uuid)','EXECUTE'),'timer read denied to '||r) from unnest(array['anon','service_role'])r;
insert into auth.users(id,email_confirmed_at) values (md5('timer_a')::uuid,clock_timestamp()),(md5('timer_b')::uuid,clock_timestamp());
insert into profiles(id,display_name) values(md5('timer_a')::uuid,'Timer A'),(md5('timer_b')::uuid,'Timer B');
insert into account_preferences(owner_id) values(md5('timer_a')::uuid),(md5('timer_b')::uuid);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('timer_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.timer_w',start_ad_hoc_workout()::text,true);
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '30 minutes',last_activity_at=clock_timestamp()-interval '1 minute',activity_evidence_at=clock_timestamp()-interval '1 minute' where id=current_setting('body_test.timer_w')::uuid;
set local role authenticated;
select set_config('body_test.activity',(select last_activity_at::text from workout_sessions where id=current_setting('body_test.timer_w')::uuid),true);
select is((set_workout_pause(current_setting('body_test.timer_w')::uuid,true,0,md5('pause_1')::uuid)->>'timer_revision')::int,1,'pause advances server revision');
select ok((select manual_paused_at is not null from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'manual pause persists');
select is((select last_activity_at::text from workout_sessions where id=current_setting('body_test.timer_w')::uuid),current_setting('body_test.activity'),'timer controls do not extend inactivity');
select is((set_workout_pause(current_setting('body_test.timer_w')::uuid,true,0,md5('pause_1')::uuid)->>'timer_revision')::int,1,'same pause retry is idempotent');
select throws_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,false,0,md5('pause_1')::uuid)$$,'23514',null,'retry payload cannot be changed');
select throws_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,false,0,md5('stale_resume')::uuid)$$,'40001',null,'stale competing command rejected');
select lives_ok($$select workout_continuity(current_setting('body_test.timer_w')::uuid)$$,'refresh is a passive verified read');
select ok((select manual_paused_at is not null from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'passive read never resumes');
select lives_ok($$update workout_sessions set name=name where id=current_setting('body_test.timer_w')::uuid$$,'direct no-op remains allowed');
select ok((select manual_paused_at is not null from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'no-op update never resumes');
select throws_ok($$update workout_sessions set manual_paused_at=null where id=current_setting('body_test.timer_w')::uuid$$,'42501',null,'cannot directly edit pause time');
select throws_ok($$update workout_sessions set timer_command='{"paused":true,"revision":1,"request":"12345678-1234-1234-1234-123456789012","seconds":999}'::jsonb where id=current_setting('body_test.timer_w')::uuid$$,'22023',null,'cannot submit a client duration');
reset role;
update workout_sessions set manual_paused_at=clock_timestamp()-interval '5 minutes' where id=current_setting('body_test.timer_w')::uuid;
set local role authenticated;
select set_config('body_test.frozen',workout_active_seconds(current_setting('body_test.timer_w')::uuid)::text,true);
select ok(abs(current_setting('body_test.frozen')::numeric-1500)<2,'effective clock excludes an ongoing pause');
select pg_sleep(0.05);
select ok(abs(workout_active_seconds(current_setting('body_test.timer_w')::uuid)-current_setting('body_test.frozen')::numeric)<0.001,'paused effective clock remains frozen across reads');
select is((set_workout_pause(current_setting('body_test.timer_w')::uuid,false,1,md5('resume_1')::uuid)->>'timer_revision')::int,2,'resume advances revision');
select is((select jsonb_array_length(manual_pause_intervals) from workout_sessions where id=current_setting('body_test.timer_w')::uuid),1,'one pause period recorded');
select lives_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,false,1,md5('resume_1')::uuid)$$,'resume retry is idempotent');
select is((select jsonb_array_length(manual_pause_intervals) from workout_sessions where id=current_setting('body_test.timer_w')::uuid),1,'resume retry never double counts');
select set_config('request.jwt.claims',json_build_object('sub',md5('timer_b')::uuid,'role','authenticated')::text,true);
select is(workout_active_seconds(current_setting('body_test.timer_w')::uuid),null::numeric,'foreign timer reveals no private state');
select throws_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,true,2,md5('foreign_pause')::uuid)$$,'42501',null,'foreign owner cannot pause');
select set_config('request.jwt.claims',json_build_object('sub',md5('timer_a')::uuid,'role','authenticated')::text,true);
select lives_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,true,2,md5('pause_2')::uuid)$$,'pause before verified selection');
select set_config('body_test.timer_item',edit_workout(current_setting('body_test.timer_w')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select ok((select manual_paused_at is null from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'verified exercise selection automatically resumes');
select is((select timer_revision from workout_sessions where id=current_setting('body_test.timer_w')::uuid),4,'automatic set structure resumes only once');
select lives_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,true,4,md5('pause_3')::uuid)$$,'pause before logging');
select lives_ok($$select log_workout_set(current_setting('body_test.timer_item')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.timer_item')::uuid order by position limit 1),'save',0,md5('timer_set')::uuid,8,60,'working','external',true)$$,'same set logger saves actual performance');
select ok((select manual_paused_at is null from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'verified saved set automatically resumes');
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.timer_item')::uuid and actual_reps=8 and actual_weight_kg=60 and status='completed'),1,'timer never rewrites actual performance');
select lives_ok($$select set_workout_pause(current_setting('body_test.timer_w')::uuid,true,6,md5('pause_expiry')::uuid)$$,'pause does not disable expiry');
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '15 hours',last_activity_at=clock_timestamp()-interval '13 hours',activity_evidence_at=clock_timestamp()-interval '13 hours',manual_paused_at=clock_timestamp()-interval '12 hours' where id=current_setting('body_test.timer_w')::uuid;
set local role authenticated;
select is(set_workout_pause(current_setting('body_test.timer_w')::uuid,false,7,md5('expire_resume')::uuid)->>'state','expired','expired resume commits authoritative cleanup');
select is((select status from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'abandoned','paused session never stays indefinitely open');
select is((select duration_kind from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'estimated','recovered duration retains its original classification');
select is((select effective_finished_at from workout_sessions where id=current_setting('body_test.timer_w')::uuid),(select last_activity_at from workout_sessions where id=current_setting('body_test.timer_w')::uuid),'recovered endpoint remains saved activity, not closure');
select is((select manual_paused_at from workout_sessions where id=current_setting('body_test.timer_w')::uuid),null::timestamptz,'closed clock has no ongoing pause');
select set_config('body_test.timer_closed',start_ad_hoc_workout()::text,true);
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '30 minutes',last_activity_at=clock_timestamp(),activity_evidence_at=clock_timestamp(),manual_paused_at=clock_timestamp()-interval '10 minutes' where id=current_setting('body_test.timer_closed')::uuid;
set local role authenticated;
select lives_ok($$select end_workout(current_setting('body_test.timer_closed')::uuid,'completed')$$,'ordinary finish while paused preserves closure flow');
select ok(abs(workout_active_seconds(current_setting('body_test.timer_closed')::uuid)-1200)<2,'closed effective time excludes final pause');
select ok(abs((training_progress('30','UTC')->'summary'->>'average_seconds')::numeric-1200)<2,'reliable analytics uses pause-adjusted duration');
select throws_ok($$select set_workout_pause(current_setting('body_test.timer_closed')::uuid,false,0,md5('closed_timer')::uuid)$$,'23514',null,'closed timer cannot resume');
select set_config('body_test.legacy',start_ad_hoc_workout()::text,true);
reset role;
update workout_sessions set last_activity_at=null,activity_evidence_at=null,started_at=clock_timestamp()-interval '2 days' where id=current_setting('body_test.legacy')::uuid;
set local role authenticated;
select throws_ok($$select set_workout_pause(current_setting('body_test.legacy')::uuid,true,0,md5('legacy_pause')::uuid)$$,'23514',null,'untracked legacy timer cannot bypass inactivity expiry');
select is((select last_activity_at from workout_sessions where id=current_setting('body_test.legacy')::uuid),null::timestamptz,'timer rejection does not invent legacy activity');
select lives_ok($$select workout_continuity(current_setting('body_test.legacy')::uuid,md5('legacy_continue')::uuid)$$,'explicit existing continuation establishes legacy anchor');
select lives_ok($$select set_workout_pause(current_setting('body_test.legacy')::uuid,true,0,md5('legacy_pause_valid')::uuid)$$,'tracked legacy workout supports normal pause rules');
select lives_ok($$select workout_continuity(current_setting('body_test.legacy')::uuid,md5('legacy_continue_again')::uuid)$$,'deliberate continuation also resumes a paused timer');
select is((select manual_paused_at from workout_sessions where id=current_setting('body_test.legacy')::uuid),null::timestamptz,'explicit continuation closes the pause without invented performance');
select * from finish();rollback;
